import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

class Completed {

    public double[] calcEquation(
        List<List<String>> equations,
        double[] values,
        List<List<String>> queries
    ) {

        Map<String, List<Edge>> graph = new HashMap<>();

        for (int i = 0; i < equations.size(); i++) {
            String a = equations.get(i).get(0);
            String b = equations.get(i).get(1);
            double value = values[i];

            graph.computeIfAbsent(a, key -> new ArrayList<>()).add(new Edge(b, value));
            graph.computeIfAbsent(b, key -> new ArrayList<>()).add(new Edge(a, 1.0 / value));
        }

        double[] answers = new double[queries.size()];

        for (int i = 0; i < queries.size(); i++) {
            String start = queries.get(i).get(0);
            String end = queries.get(i).get(1);
            answers[i] = evaluate(start, end, graph);
        }

        return answers;
    }

    private double evaluate(String start, String end, Map<String, List<Edge>> graph) {

        if (!graph.containsKey(start) || !graph.containsKey(end)) {
            return -1.0;
        }

        if (start.equals(end)) {
            return 1.0;
        }

        Set<String> visited = new HashSet<>();
        return dfs(start, end, 1.0, graph, visited);
    }

    private double dfs(
        String current,
        String target,
        double product,
        Map<String, List<Edge>> graph,
        Set<String> visited
    ) {

        if (current.equals(target)) {
            return product;
        }

        visited.add(current);

        for (Edge edge : graph.get(current)) {
            if (visited.contains(edge.to)) {
                continue;
            }

            double result = dfs(edge.to, target, product * edge.weight, graph, visited);
            if (result != -1.0) {
                return result;
            }
        }

        return -1.0;
    }

    private static class Edge {

        final String to;
        final double weight;

        Edge(String to, double weight) {
            this.to = to;
            this.weight = weight;
        }
    }
}

