import org.junit.jupiter.api.Disabled;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;

@DisplayName("100/92_evaluate_division (incomplete)")
class SolutionIncompleteTest {

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldAnswerQueriesFromConnectedVariables() {

        Solution solution = new Solution();

        List<List<String>> equations = Arrays.asList(
            Arrays.asList("a", "b"),
            Arrays.asList("b", "c")
        );
        double[] values = {2.0, 3.0};
        List<List<String>> queries = Arrays.asList(
            Arrays.asList("a", "c"),
            Arrays.asList("b", "a"),
            Arrays.asList("a", "e"),
            Arrays.asList("a", "a"),
            Arrays.asList("x", "x")
        );

        double[] result = solution.calcEquation(equations, values, queries);

        assertArrayEquals(new double[]{6.0, 0.5, -1.0, 1.0, -1.0}, result, 1e-5);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldHandleMultiLetterVariables() {

        Solution solution = new Solution();

        List<List<String>> equations = Arrays.asList(
            Arrays.asList("a", "b"),
            Arrays.asList("b", "c"),
            Arrays.asList("bc", "cd")
        );
        double[] values = {1.5, 2.5, 5.0};
        List<List<String>> queries = Arrays.asList(
            Arrays.asList("a", "c"),
            Arrays.asList("c", "b"),
            Arrays.asList("bc", "cd"),
            Arrays.asList("cd", "bc")
        );

        double[] result = solution.calcEquation(equations, values, queries);

        assertArrayEquals(new double[]{3.75, 0.4, 5.0, 0.2}, result, 1e-5);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldReturnNegativeOneForUnknownVariables() {

        Solution solution = new Solution();

        List<List<String>> equations = Arrays.asList(Arrays.asList("a", "b"));
        double[] values = {0.5};
        List<List<String>> queries = Arrays.asList(
            Arrays.asList("a", "b"),
            Arrays.asList("b", "a"),
            Arrays.asList("a", "c"),
            Arrays.asList("x", "y")
        );

        double[] result = solution.calcEquation(equations, values, queries);

        assertArrayEquals(new double[]{0.5, 2.0, -1.0, -1.0}, result, 1e-5);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldReturnOneForSameKnownVariable() {

        Solution solution = new Solution();

        List<List<String>> equations = Arrays.asList(Arrays.asList("x", "y"));
        double[] values = {3.0};
        List<List<String>> queries = Arrays.asList(Arrays.asList("x", "x"));

        double[] result = solution.calcEquation(equations, values, queries);

        assertArrayEquals(new double[]{1.0}, result, 1e-5);
    }
}

